#include "nvfs_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static void _init_ (UInt16 nvram_base , UInt16 nvram_size) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

NVFS_Status nvfs_init (UInt16 fs_base , UInt16 fs_size , Boolean do_format)
{
  int status = NVFS_IRQ_CALL_FAILED ;

  nvfs_atomic_init () ;

  if (nvfs_atomic_request ())
    {
      if ((status = setjmp (nvfs_vars.throw_vec)) == 0)
        {
          _init_ (fs_base , fs_size) ;

          (do_format ? nvfs_init_format : nvfs_init_existing) () ;
        }

      nvfs_atomic_release () ;
    }

  return (NVFS_Status) status ;
}

//--------------------------------------------------------------------------//

static void _init_ (UInt16 fs_base , UInt16 fs_size)
{
  if (fs_base + fs_size > NVRAM_SIZE || fs_size <= sizeof (NVFS_Header))
    {
      nvfs_throw (NVFS_ERROR) ;
    }

  nvfs_vars.nvram.beg = fs_base               ;
  nvfs_vars.nvram.end = fs_base + fs_size - 1 ;
}

